{
  "name": "sdio_cmd52_wr",
  "confidence": "medium",
  "docstring": "Formats an SDIO CMD52 byte-write packet from a command-slot table and sends it through the Bluetooth HCI event path.",
  "subsystem": "bt",
  "var_renames": {
    "a1": "byte_value",
    "a2": "cmd_slot",
    "v4": "cmd_pkt",
    "v5": "cmd_slot_ptr"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "CMD52 write/read flag: 0 when slot byte at offset 17 equals 1"
    },
    {
      "offset": 1,
      "meaning": "byte value to write, from a1"
    },
    {
      "offset": 2,
      "meaning": "slot byte at offset 22 copied into the packet"
    },
    {
      "offset": 4,
      "meaning": "slot 16-bit field at offset 20 copied into the packet"
    },
    {
      "offset": 6,
      "meaning": "slot 16-bit field at offset 12 copied into the packet"
    }
  ]
}
